public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while ((result & 0x80) != 0) {
        int byteValue = inputStream.read();
        if (byteValue == -1) {
            throw new EOFException("Unexpected end of stream");
        }
        result |= (byteValue & 0x7F) << shift;
        shift += 7;
    }
    return result;
}

